function renderStatusPage(parsedSysData) {
    let html = '';
    try {
        // 全局变量保护
        if (!window.currentIdolNameForStatus) {
            window.currentIdolNameForStatus = (parsedSysData.status && parsedSysData.status['当前偶像']) || '';
        }
        if (!window.currentIdolNameForStatus && typeof idolDatabase !== 'undefined' && idolDatabase.length > 0) {
            window.currentIdolNameForStatus = idolDatabase[0].name;
        }

        html += '<div id="page-status" class="page">';

        // 1. 顶部头像选择列表
        html += '<div class="idol-list-container">';
        if (typeof idolDatabase !== 'undefined' && idolDatabase.length > 0) {
            idolDatabase.forEach(idol => {
                let activeClass = (idol.name === window.currentIdolNameForStatus) ? 'active' : '';
                let lockedClass = (typeof checkIsUnlocked === 'function' && !checkIsUnlocked(idol.name)) ? 'locked' : '';
                let avatarUrl = typeof getAssetUrl === 'function' ? getAssetUrl(idol.name + "_头像", "avatar") : '';
                html += `<div class="idol-mini-wrap ${activeClass} ${lockedClass}" onclick="switchStatusIdol('${idol.name}')" title="${idol.name}">
                            <img src="${avatarUrl}" class="idol-mini-avatar">
                            <div class="idol-mini-name">${idol.name}</div>
                         </div>`;
            });
        }
        html += '</div>';

        // 数据防呆
        // ======= MVU 数据直读与映射拦截 =======
        var sData = {};
        var isCurrentStatus = true; // MVU直读始终为最新状态
        try {
            let allVars = typeof getAllVariables === 'function' ? getAllVariables() : {};
            let idolName = window.currentIdolNameForStatus;
            let idolData = _.get(allVars, `stat_data.登场艺人名单.${idolName}`, null);

            if (idolData) {
                sData['当前偶像'] = idolName;

                // 映射心理与姿势
                if(idolData.心理与互动状态) {
                    sData['姿势'] = idolData.心理与互动状态.当前姿势 || '-';
                    sData['心声'] = idolData.心理与互动状态.当前心理 || '...';
                }

                // 映射核心生理与深度监察
                if(idolData.生理与开发状态) {
                    sData['生理状态'] = idolData.生理与开发状态.生理期状态 || '-';
                    sData['处女膜'] = idolData.生理与开发状态.处女膜状态 || '-';
                    sData['皮肤'] = idolData.生理与开发状态.皮肤 || '-';
                    sData['口腔'] = idolData.生理与开发状态.口腔 || '-';
                    sData['胸部'] = idolData.生理与开发状态.胸部 || '-';
                    sData['乳头'] = idolData.生理与开发状态.乳头 || '-';
                    sData['臀部'] = idolData.生理与开发状态.臀部 || '-';
                    sData['小穴'] = idolData.生理与开发状态.小穴 || '-';
                    sData['菊花'] = idolData.生理与开发状态.菊花 || '-';
                    sData['子宫'] = idolData.生理与开发状态.子宫 || '-';
                }

                // 映射衣物着装
                if(idolData.穿着与衣物) {
                    sData['上衣'] = idolData.穿着与衣物.上衣 || '-';
                    sData['下衣'] = idolData.穿着与衣物.下衣 || '-';
                    sData['内衣'] = idolData.穿着与衣物.内衣 || '-';
                    sData['内裤'] = idolData.穿着与衣物.内裤 || '-';
                    sData['鞋袜'] = idolData.穿着与衣物.鞋袜 || '-';
                    sData['持有佩戴品'] = idolData.穿着与衣物.饰品配件 || '-';
                }

                // 映射性爱经验
                if(idolData.经验记录) {
                    sData['性爱次数'] = idolData.经验记录.综合性经验_Total || 0;
                    sData['口交次数'] = idolData.经验记录.口交次数 || 0;
                    sData['乳交次数'] = idolData.经验记录.乳交次数 || 0;
                    sData['手交次数'] = idolData.经验记录.手交次数 || 0;
                    sData['阴道交次数'] = idolData.经验记录.阴道交次数 || 0;
                    sData['肛交次数'] = idolData.经验记录.肛交次数 || 0;
                    sData['中出次数'] = idolData.经验记录.体内中出次数 || 0;
                }
            }
        } catch(e) {
            console.error("提取 MVU 状态数据失败", e);
        }
        // ===================================

        let currentStatusUnlocked = (typeof checkIsUnlocked === 'function') ? checkIsUnlocked(window.currentIdolNameForStatus) : true;

        let avatarImg = typeof getAssetUrl === 'function' ? getAssetUrl(window.currentIdolNameForStatus + "_立绘", "avatar") : '';
        if (!avatarImg) avatarImg = typeof getAssetUrl === 'function' ? getAssetUrl(window.currentIdolNameForStatus + "_头像", "avatar") : '';

        // 主控制台容器
        html += `<div class="dashboard">`;

        // 左侧：身份卡片
        html += `<div class="s-column identity-col">
                    <div class="char-name">${window.currentIdolNameForStatus || '未知偶像'}</div>
                    <div class="char-img-placeholder ${currentStatusUnlocked ? '' : 'locked'}">
                        <img src="${avatarImg}" onerror="this.style.display='none'">
                    </div>
                    <div class="status-tag">
                        <i class="bi bi-person-fill"></i>
                        <div><b>当前姿势：</b><br><span style="color: var(--s-text-dark);">${isCurrentStatus ? (sData['姿势']||'站立') : '-'}</span></div>
                    </div>
                    <div class="status-tag" style="background: var(--s-bg-color);">
                        <i class="bi bi-chat-dots-fill"></i>
                        <div><b>当前心理：</b><br><span style="color: var(--s-text-dark);">${isCurrentStatus ? ('“'+(sData['心声']||'...')+'”') : '等待数据同步...'}</span></div>
                    </div>
                 </div>`;

        // 右侧：交互控制台
        html += `<div class="s-column hub-col">
                    <div class="hub-card health-card">
                        <div class="hub-card-title"><i class="bi bi-heart-pulse-fill"></i> 核心生理状态</div>
                        <div class="health-grid">
                            <div class="health-item">
                                <i class="bi bi-droplet-fill"></i>
                                <div><span>生理期状态</span><span>${isCurrentStatus ? (sData['生理状态']||'-') : '-'}</span></div>
                            </div>
                            <div class="health-item">
                                <i class="bi bi-shield-check"></i>
                                <div><span>处女膜状态</span><span>${isCurrentStatus ? (sData['处女膜']||'-') : '-'}</span></div>
                            </div>
                        </div>
                    </div>

                    <div class="hub-card">
                        <div class="hub-card-left">
                            <div class="hub-card-title"><i class="bi bi-bag-heart-fill"></i> 外观与着装</div>
                            <div class="hub-card-desc">查看当前上衣、下装、内衣及饰品状态</div>
                        </div>
                        <button class="hub-btn" onclick="openSubPanel('pad-status-gear')">查看详情 <i class="bi bi-chevron-right" style="margin:0 0 0 5px; color:#fff;"></i></button>
                    </div>

                    <div class="hub-card">
                        <div class="hub-card-left">
                            <div class="hub-card-title"><i class="bi bi-activity"></i> 深度身体监察</div>
                            <div class="hub-card-desc">检查皮肤、口腔、胸部、下体等细微生理反应</div>
                        </div>
                        <button class="hub-btn" onclick="openSubPanel('pad-status-body')">执行监察 <i class="bi bi-chevron-right" style="margin:0 0 0 5px; color:#fff;"></i></button>
                    </div>

                    <div class="hub-card">
                        <div class="hub-card-left">
                            <div class="hub-card-title"><i class="bi bi-journal-text"></i> 性爱经验档案</div>
                            <div class="hub-card-desc">查阅各部位开发进度与累计性经验</div>
                        </div>
                        <button class="hub-btn" onclick="openSubPanel('pad-status-exp')">调阅档案 <i class="bi bi-chevron-right" style="margin:0 0 0 5px; color:#fff;"></i></button>
                    </div>
                 </div>`;

        // ================= 隐藏的子面板 =================

        // 1. 着装子面板 (★已替换全部自定义图标接口★)
        html += `<div class="sub-panel" id="pad-status-gear">
                    <div class="sub-panel-header">
                        <button class="btn-sub-back" onclick="closeSubPanel('pad-status-gear')"><i class="bi bi-arrow-left" style="margin:0;"></i></button>
                        <div class="sub-panel-title"><i class="bi bi-bag-heart-fill"></i> 外观着装状态</div>
                    </div>
                    <div class="sub-panel-content">
                        <div class="gear-list">
                            <div class="gear-item"><div class="gear-label">${customIcons['上衣']} 上衣</div><div class="gear-text">${isCurrentStatus ? (sData['上衣']||'-') : '-'}</div></div>
                            <div class="gear-item"><div class="gear-label">${customIcons['下衣']} 下衣</div><div class="gear-text">${isCurrentStatus ? (sData['下衣']||'-') : '-'}</div></div>
                            <div class="gear-item"><div class="gear-label">${customIcons['内衣']} 内衣</div><div class="gear-text">${isCurrentStatus ? (sData['内衣']||'-') : '-'}</div></div>
                            <div class="gear-item"><div class="gear-label">${customIcons['内裤']} 内裤</div><div class="gear-text">${isCurrentStatus ? (sData['内裤']||'-') : '-'}</div></div>
                            <div class="gear-item" style="grid-column:1/-1;"><div class="gear-label">${customIcons['鞋袜']} 鞋袜</div><div class="gear-text">${isCurrentStatus ? (sData['鞋袜']||'-') : '-'}</div></div>
                            <div class="gear-item" style="grid-column:1/-1;"><div class="gear-label">${customIcons['饰品配件']} 饰品配件</div><div class="gear-text">${isCurrentStatus ? (sData['持有佩戴品']||'-') : '-'}</div></div>
                        </div>
                    </div>
                 </div>`;

        // 2. 身体监察子面板 (★已替换全部自定义图标接口★)
        html += `<div class="sub-panel" id="pad-status-body">
                    <div class="sub-panel-header">
                        <button class="btn-sub-back" onclick="closeSubPanel('pad-status-body')"><i class="bi bi-arrow-left" style="margin:0;"></i></button>
                        <div class="sub-panel-title"><i class="bi bi-activity"></i> 深度身体监察报告</div>
                    </div>
                    <div class="sub-panel-content">
                        <div class="body-list">
                            <div class="body-node"><div class="node-title">${customIcons['皮肤']} 皮肤</div><div class="node-text">${isCurrentStatus ? (sData['皮肤']||'-') : '-'}</div></div>
                            <div class="body-node"><div class="node-title">${customIcons['口腔']} 口腔</div><div class="node-text">${isCurrentStatus ? (sData['口腔']||'-') : '-'}</div></div>
                            <div class="body-node sensitive"><div class="node-title node-sensitive-title">${customIcons['胸部']} 胸部</div><div class="node-text">${isCurrentStatus ? (sData['胸部']||'-') : '-'}</div></div>
                            <div class="body-node sensitive"><div class="node-title node-sensitive-title">${customIcons['乳头']} 乳头</div><div class="node-text">${isCurrentStatus ? (sData['乳头']||'-') : '-'}</div></div>
                            <div class="body-node"><div class="node-title">${customIcons['臀部']} 臀部</div><div class="node-text">${isCurrentStatus ? (sData['臀部']||'-') : '-'}</div></div>
                            <div class="body-node sensitive"><div class="node-title node-sensitive-title">${customIcons['小穴']} 小穴</div><div class="node-text">${isCurrentStatus ? (sData['小穴']||'-') : '-'}</div></div>
                            <div class="body-node"><div class="node-title">${customIcons['菊花']} 菊花</div><div class="node-text">${isCurrentStatus ? (sData['菊花']||'-') : '-'}</div></div>
                            <div class="body-node"><div class="node-title">${customIcons['子宫']} 子宫</div><div class="node-text">${isCurrentStatus ? (sData['子宫']||'-') : '-'}</div></div>
                        </div>
                    </div>
                 </div>`;

        // 3. 经验统计子面板 (★已替换全部自定义图标接口★)
        html += `<div class="sub-panel" id="pad-status-exp">
                    <div class="sub-panel-header">
                        <button class="btn-sub-back" onclick="closeSubPanel('pad-status-exp')"><i class="bi bi-arrow-left" style="margin:0;"></i></button>
                        <div class="sub-panel-title"><i class="bi bi-journal-text"></i> 性爱经验档案</div>
                    </div>
                    <div class="sub-panel-content">
                        <div style="text-align: center; margin-bottom: 20px; padding: 20px; background: white; border-radius: 16px; border: 1px solid var(--s-glass-border); box-shadow: 0 4px 10px rgba(0,0,0,0.02);">
                            <div style="font-size: 14px; color: var(--s-text-light); font-weight: bold; margin-bottom: 5px;">综合性经验 (Total)</div>
                            <div style="font-size: 36px; font-weight: 900; color: var(--s-accent); display: flex; justify-content: center; align-items: center;">
                                <i class="bi bi-infinity" style="margin-right: 10px; color: var(--s-primary);"></i>
                                ${isCurrentStatus ? (sData['性爱次数']||'0') : '0'} <span style="font-size: 16px; margin-left: 5px; color: var(--s-text-light);">次</span>
                            </div>
                        </div>
                        <div class="exp-grid">
                            <div class="exp-item"><div class="exp-icon">${customIcons['口交']}</div><div class="exp-label">口交次数</div><div class="exp-val">${isCurrentStatus ? (sData['口交次数']||'0') : '0'}</div></div>
                            <div class="exp-item"><div class="exp-icon">${customIcons['乳交']}</div><div class="exp-label">乳交次数</div><div class="exp-val">${isCurrentStatus ? (sData['乳交次数']||'0') : '0'}</div></div>
                            <div class="exp-item"><div class="exp-icon">${customIcons['手交']}</div><div class="exp-label">手交次数</div><div class="exp-val">${isCurrentStatus ? (sData['手交次数']||'0') : '0'}</div></div>
                            <div class="exp-item"><div class="exp-icon">${customIcons['阴道交']}</div><div class="exp-label">阴道交次数</div><div class="exp-val">${isCurrentStatus ? (sData['阴道交次数']||'0') : '0'}</div></div>
                            <div class="exp-item"><div class="exp-icon">${customIcons['肛交']}</div><div class="exp-label">肛交次数</div><div class="exp-val">${isCurrentStatus ? (sData['肛交次数']||'0') : '0'}</div></div>
                            <div class="exp-item"><div class="exp-icon">${customIcons['中出']}</div><div class="exp-label">体内中出</div><div class="exp-val">${isCurrentStatus ? (sData['中出次数']||'0') : '0'}</div></div>
                        </div>
                    </div>
                 </div>`;

        html += `</div>`; // dashboard
        html += '</div>'; // page-status

    } catch(err) {
        console.error("渲染状态页时出错:", err);
        html += `<div id="page-status" class="page"><div style="padding:50px;text-align:center;color:#ef4444;font-weight:bold;">📊 状态数据报错了：<br>${err.message}</div></div>`;
    }
    return html;
}
